import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b != -1 && b <= ' ') {
                b = readByte();
            }
            if (b == -1) return 0;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            long val = 0;
            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -val : val;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    static class Line implements Comparable<Line> {
        long y1, y2;

        Line(long y1, long y2) {
            this.y1 = y1;
            this.y2 = y2;
        }

        @Override
        public int compareTo(Line o) {
            if (this.y1 != o.y1) {
                return Long.compare(this.y1, o.y1);
            }
            // Para mesmo y1, ordena por y2 decrescente
            return Long.compare(o.y2, this.y2);
        }
    }

    static class FenwickTree {
        int[] tree;
        int n;

        FenwickTree(int n) {
            this.n = n;
            this.tree = new int[n + 1];
        }

        void add(int i, int delta) {
            for (; i <= n; i += i & -i) {
                tree[i] += delta;
            }
        }

        int query(int i) {
            int sum = 0;
            for (; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        long x1 = scanner.nextLong();
        long x2 = scanner.nextLong();

        Line[] lines = new Line[n];
        long[] y2Vals = new long[n];

        for (int i = 0; i < n; i++) {
            long a = scanner.nextLong();
            long b = scanner.nextLong();
            long y1 = a * x1 + b;
            long y2 = a * x2 + b;
            lines[i] = new Line(y1, y2);
            y2Vals[i] = y2;
        }

        // Compressão de coordenadas para Y2
        Arrays.sort(y2Vals);
        int uniqueCount = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || y2Vals[i] != y2Vals[i - 1]) {
                y2Vals[uniqueCount++] = y2Vals[i];
            }
        }

        // Ordena as retas por (y1 asc, y2 desc)
        Arrays.sort(lines);

        FenwickTree bit = new FenwickTree(uniqueCount);
        long noIntersection = 0;

        for (int i = 0; i < n; i++) {
            // Busca binária para achar o índice de lines[i].y2 no array comprimido
            int rank = Arrays.binarySearch(y2Vals, 0, uniqueCount, lines[i].y2);
            // Elementos com Y2 estritamente menor que lines[i].y2 têm rank < rank atual
            // Na Fenwick tree 1-indexada, rank vai de 0 a uniqueCount - 1,
            // então a quantidade de valores estritamente menores é bit.query(rank)
            noIntersection += bit.query(rank);
            bit.add(rank + 1, 1);
        }

        long totalPairs = (long) n * (n - 1) / 2;
        long ans = totalPairs - noIntersection;

        System.out.println(ans);
    }
}
